-- Twenty award/ranking-informed plant-forward recipes. Nutrition is a planning
-- estimate from formulation weights and USDA FoodData Central reference foods.

with source(id,name,slot,cuisine,origin,diet,image,kcal,protein,fiber,score,allergens,ingredients,instructions,description) as (values
('recipe_award_karantika','Algerian Karantika','breakfast','Algerian','Algeria','vegetarian','algerian-karantika.webp',410,22,11,89,array['egg'],
 '[{"name":"Chickpea flour","amount_g":220},{"name":"Eggs","amount_g":150},{"name":"Water","amount_g":650},{"name":"Olive oil","amount_g":25},{"name":"Ground cumin","amount_g":5},{"name":"Harissa","amount_g":20}]'::jsonb,
 '[{"text":"Whisk chickpea flour, water, eggs, oil, cumin and salt until smooth; rest 20 minutes."},{"text":"Pour into an oiled hot baking dish and bake at 220°C for 30–35 minutes until set and bronzed."},{"text":"Cool five minutes; finish with harissa, cumin and lemon."}]'::jsonb,'Custardy chickpea bake with cumin, harissa and lemon.'),
('recipe_award_masala_dosa','Masala Dosa','breakfast','South Indian','India','vegan','indian-masala-dosa.webp',485,15,10,91,array['mustard'],
 '[{"name":"Dosa rice","amount_g":260},{"name":"Urad dal","amount_g":90},{"name":"Potato","amount_g":500},{"name":"Onion","amount_g":180},{"name":"Peas","amount_g":180},{"name":"Rapeseed oil","amount_g":25}]'::jsonb,
 '[{"text":"Soak rice and dal separately, blend with water, combine and ferment 8–12 hours."},{"text":"Cook onion, mustard seed and spices; fold through crushed potato and peas."},{"text":"Spread batter thinly on a hot pan, crisp with minimal oil, fill and fold."}]'::jsonb,'Fermented rice-lentil crepe wrapped around bright spiced potato and peas.'),
('recipe_award_ful_medames','Egyptian Ful Medames','breakfast','Egyptian','Egypt','vegan','egyptian-ful-medames.webp',440,21,16,94,array['sesame'],
 '[{"name":"Cooked fava beans","amount_g":900},{"name":"Tomato","amount_g":300},{"name":"Tahini","amount_g":60},{"name":"Lemon juice","amount_g":70},{"name":"Olive oil","amount_g":25},{"name":"Cumin","amount_g":5}]'::jsonb,
 '[{"text":"Warm beans with cumin and a splash of water; crush one-third for body."},{"text":"Whisk tahini with lemon, garlic and cool water."},{"text":"Spoon over beans and finish with tomato, herbs and olive oil."}]'::jsonb,'Slow-warmed fava beans with tahini, tomato, cumin and lemon.'),
('recipe_award_kanda_poha','Kanda Poha with Peas and Peanuts','breakfast','Maharashtrian','India','vegan','indian-kanda-poha.webp',425,13,8,88,array['peanut'],
 '[{"name":"Thick poha","amount_g":320},{"name":"Onion","amount_g":240},{"name":"Peas","amount_g":240},{"name":"Peanuts","amount_g":80},{"name":"Rapeseed oil","amount_g":25},{"name":"Lime juice","amount_g":50}]'::jsonb,
 '[{"text":"Rinse poha briefly and drain until supple, not mushy."},{"text":"Toast peanuts; cook mustard seed, curry leaf, onion, chilli and turmeric."},{"text":"Fold in peas and poha, steam five minutes, then add lime and herbs."}]'::jsonb,'Turmeric-fluffed rice with onion, peas, peanuts and lime.'),
('recipe_award_aloo_paratha','Wholegrain Aloo Paratha','breakfast','Punjabi','India','vegetarian','indian-aloo-paratha.webp',505,18,11,86,array['wheat','milk'],
 '[{"name":"Whole-wheat flour","amount_g":360},{"name":"Potato","amount_g":600},{"name":"Peas","amount_g":200},{"name":"Greek yogurt","amount_g":240},{"name":"Rapeseed oil","amount_g":25},{"name":"Garam masala","amount_g":6}]'::jsonb,
 '[{"text":"Knead flour with warm water and rest 20 minutes."},{"text":"Mash potato, peas, ginger, chilli, spices and herbs."},{"text":"Enclose filling in dough, roll gently and griddle with a light film of oil; serve with yogurt."}]'::jsonb,'Wholegrain flatbread filled with spiced potato and peas, with yogurt.'),
('recipe_award_dal_tadka','Dal Tadka','lunch','Indian','India','vegan','indian-dal-tadka.webp',465,24,17,95,array[]::text[],
 '[{"name":"Toor dal","amount_g":320},{"name":"Tomato","amount_g":350},{"name":"Onion","amount_g":220},{"name":"Garlic","amount_g":20},{"name":"Rapeseed oil","amount_g":25},{"name":"Whole-wheat roti","amount_g":240}]'::jsonb,
 '[{"text":"Simmer rinsed dal with turmeric until creamy."},{"text":"Cook onion and tomato until jammy; fold into dal."},{"text":"Bloom cumin, garlic and chilli in oil, pour over the dal and serve with roti."}]'::jsonb,'Golden lentils under an aromatic cumin, garlic and chilli tempering.'),
('recipe_award_gado_gado','Gado-Gado','lunch','Indonesian','Indonesia','vegetarian','indonesian-gado-gado.webp',520,28,13,91,array['peanut','soy','egg'],
 '[{"name":"Firm tofu","amount_g":400},{"name":"Tempeh","amount_g":300},{"name":"Mixed vegetables","amount_g":900},{"name":"Eggs","amount_g":200},{"name":"Peanut butter","amount_g":120},{"name":"Lime juice","amount_g":55}]'::jsonb,
 '[{"text":"Steam vegetables until just tender; sear tofu and tempeh."},{"text":"Whisk peanut butter, lime, chilli, tamari and warm water into a pourable sauce."},{"text":"Arrange with halved eggs and spoon over sauce just before serving."}]'::jsonb,'Vegetables, tofu, tempeh and egg dressed with peanut-lime sauce.'),
('recipe_award_kisir','Turkish Kısır','lunch','Turkish','Türkiye','vegan','turkish-kisir.webp',430,13,12,92,array['wheat'],
 '[{"name":"Fine bulgur","amount_g":320},{"name":"Tomato","amount_g":350},{"name":"Pepper paste","amount_g":60},{"name":"Parsley","amount_g":100},{"name":"Pomegranate molasses","amount_g":45},{"name":"Olive oil","amount_g":35}]'::jsonb,
 '[{"text":"Cover bulgur with boiling water and rest covered 15 minutes."},{"text":"Massage in pepper paste, tomato, oil, lemon and pomegranate molasses."},{"text":"Fold in abundant herbs and scallions; serve in crisp lettuce leaves."}]'::jsonb,'Peppery bulgur salad with tomato, herbs, lemon and pomegranate.'),
('recipe_award_fattoush','Lebanese Chickpea Fattoush','lunch','Lebanese','Lebanon','vegan','lebanese-chickpea-fattoush.webp',455,17,14,94,array['wheat'],
 '[{"name":"Cooked chickpeas","amount_g":650},{"name":"Tomato","amount_g":450},{"name":"Cucumber","amount_g":400},{"name":"Wholegrain pita","amount_g":180},{"name":"Olive oil","amount_g":35},{"name":"Lemon juice","amount_g":70}]'::jsonb,
 '[{"text":"Toast torn pita until crisp."},{"text":"Toss vegetables, chickpeas, radish and herbs with lemon, sumac and oil."},{"text":"Fold in pita immediately before serving so it stays crisp."}]'::jsonb,'Sumac-bright chopped salad with chickpeas and crisp wholegrain pita.'),
('recipe_award_zaalouk','Moroccan Zaalouk','lunch','Moroccan','Morocco','vegan','moroccan-zaalouk.webp',360,11,12,92,array['wheat'],
 '[{"name":"Eggplant","amount_g":900},{"name":"Tomato","amount_g":600},{"name":"Wholegrain flatbread","amount_g":240},{"name":"Olive oil","amount_g":35},{"name":"Garlic","amount_g":20},{"name":"Lemon juice","amount_g":45}]'::jsonb,
 '[{"text":"Roast eggplant until collapsed and smoky; scoop and chop."},{"text":"Reduce tomato with garlic, cumin and paprika until jammy."},{"text":"Fold in eggplant, lemon and herbs; serve warm with flatbread."}]'::jsonb,'Smoky eggplant and tomato with cumin, paprika, herbs and lemon.'),
('recipe_award_shahi_paneer','Lighter Shahi Paneer','dinner','North Indian','India','vegetarian','indian-shahi-paneer.webp',560,28,7,80,array['milk','cashew'],
 '[{"name":"Paneer","amount_g":500},{"name":"Tomato","amount_g":500},{"name":"Cashews","amount_g":80},{"name":"Greek yogurt","amount_g":160},{"name":"Onion","amount_g":220},{"name":"Rapeseed oil","amount_g":25}]'::jsonb,
 '[{"text":"Soften onion, ginger, garlic and spices; add tomato and simmer."},{"text":"Blend with soaked cashews until silky, return to low heat and stir in yogurt."},{"text":"Add seared paneer and saffron; warm gently without boiling."}]'::jsonb,'Paneer in a silky saffron, cashew and tomato gravy.'),
('recipe_award_tofu_phanaeng','Tofu Phanaeng Curry','dinner','Thai','Thailand','vegan','thai-tofu-phanaeng.webp',535,24,10,90,array['soy','peanut'],
 '[{"name":"Firm tofu","amount_g":600},{"name":"Bell pepper","amount_g":450},{"name":"Light coconut milk","amount_g":500},{"name":"Brown jasmine rice","amount_g":260},{"name":"Peanuts","amount_g":50},{"name":"Phanaeng curry paste","amount_g":55}]'::jsonb,
 '[{"text":"Sear pressed tofu until golden; cook rice separately."},{"text":"Fry curry paste briefly, then add coconut milk and makrut lime leaf."},{"text":"Simmer peppers and tofu in sauce; finish with basil, lime and peanuts."}]'::jsonb,'Crisp tofu and peppers in a fragrant red coconut curry.'),
('recipe_award_youpo_mian','Xi’an Youpo Mian with Edamame','dinner','Xi’an Chinese','China','vegan','xian-youpo-mian.webp',585,24,11,89,array['wheat','soy','sesame'],
 '[{"name":"Broad wheat noodles","amount_g":400},{"name":"Shelled edamame","amount_g":400},{"name":"Bok choy","amount_g":500},{"name":"Rapeseed oil","amount_g":45},{"name":"Black vinegar","amount_g":55},{"name":"Garlic","amount_g":24}]'::jsonb,
 '[{"text":"Cook noodles, edamame and bok choy until just tender; drain well."},{"text":"Top bowls with garlic, scallion, sesame and chilli flakes."},{"text":"Heat oil until shimmering, pour over aromatics, then add black vinegar and toss."}]'::jsonb,'Broad noodles with sizzling garlic, chilli, greens and edamame.'),
('recipe_award_pav_bhaji','Wholegrain Pav Bhaji','dinner','Mumbai Indian','India','vegetarian','indian-pav-bhaji.webp',525,18,13,88,array['wheat','milk'],
 '[{"name":"Cauliflower","amount_g":500},{"name":"Potato","amount_g":500},{"name":"Peas","amount_g":350},{"name":"Tomato","amount_g":600},{"name":"Wholegrain pav","amount_g":320},{"name":"Butter","amount_g":25}]'::jsonb,
 '[{"text":"Steam cauliflower, potato and peas until tender, then mash roughly."},{"text":"Cook onion, tomato, ginger and pav bhaji masala until concentrated; add vegetables and simmer."},{"text":"Toast pav lightly with butter; serve with lemon, onion and coriander."}]'::jsonb,'Mumbai spiced vegetable mash with toasted wholegrain pav.'),
('recipe_award_pomodorini','Pomodorini Pasta with Cannellini','dinner','Italian','Italy','vegan','italian-pomodorini-cannellini.webp',570,23,14,92,array['wheat'],
 '[{"name":"Whole-wheat pasta","amount_g":360},{"name":"Cherry tomatoes","amount_g":800},{"name":"Cooked cannellini beans","amount_g":600},{"name":"Olive oil","amount_g":35},{"name":"Garlic","amount_g":20},{"name":"Fresh basil","amount_g":40}]'::jsonb,
 '[{"text":"Blister tomatoes in oil until collapsed; add garlic and chilli."},{"text":"Cook pasta al dente, reserving its water."},{"text":"Toss pasta and beans through tomatoes with basil and enough pasta water to gloss."}]'::jsonb,'Whole-wheat pasta with blistered tomatoes, basil and white beans.'),
('recipe_award_zeytoon','Zeytoon Parvardeh','snack','Iranian','Iran','vegan','iranian-zeytoon-parvardeh.webp',275,6,5,84,array['walnut'],
 '[{"name":"Green olives","amount_g":400},{"name":"Walnuts","amount_g":140},{"name":"Pomegranate molasses","amount_g":60},{"name":"Fresh herbs","amount_g":80},{"name":"Pomegranate arils","amount_g":120},{"name":"Garlic","amount_g":8}]'::jsonb,
 '[{"text":"Pulse walnuts, garlic and herbs to a coarse crumb."},{"text":"Fold with olives and pomegranate molasses."},{"text":"Chill at least one hour; finish with pomegranate arils."}]'::jsonb,'Green olives dressed with walnut, herbs and pomegranate molasses.'),
('recipe_award_pitaroudia','Rhodian Pitaroudia','snack','Rhodian Greek','Rhodes, Greece','vegan','rhodian-pitaroudia.webp',330,13,10,90,array[]::text[],
 '[{"name":"Cooked chickpeas","amount_g":700},{"name":"Tomato","amount_g":300},{"name":"Onion","amount_g":180},{"name":"Chickpea flour","amount_g":70},{"name":"Fresh mint","amount_g":35},{"name":"Olive oil","amount_g":25}]'::jsonb,
 '[{"text":"Crush chickpeas coarsely and mix with drained tomato, onion, mint and flour."},{"text":"Rest 15 minutes, shape into small patties and brush with oil."},{"text":"Bake at 220°C until deeply crisp, turning once; serve with lemon."}]'::jsonb,'Crisp Rhodian chickpea fritters with tomato, onion and mint.'),
('recipe_award_guacamole','Guacamole with Pepitas and Crudités','snack','Mexican','Mexico','vegan','mexican-guacamole-pepitas.webp',315,8,12,91,array[]::text[],
 '[{"name":"Avocado","amount_g":600},{"name":"Tomato","amount_g":220},{"name":"Pumpkin seeds","amount_g":80},{"name":"Vegetable crudités","amount_g":800},{"name":"Lime juice","amount_g":70},{"name":"Red onion","amount_g":100}]'::jsonb,
 '[{"text":"Pound onion, chilli, coriander and salt to a rough paste."},{"text":"Fold in avocado, lime and tomato, keeping the texture chunky."},{"text":"Top with toasted pepitas and serve immediately with vegetables."}]'::jsonb,'Chunky avocado, lime and tomato topped with pepitas and served with vegetables.'),
('recipe_award_bruschetta','Cannellini Bruschetta','snack','Italian','Italy','vegan','italian-cannellini-bruschetta.webp',345,13,10,92,array['wheat'],
 '[{"name":"Wholegrain sourdough","amount_g":280},{"name":"Tomato","amount_g":500},{"name":"Cooked cannellini beans","amount_g":400},{"name":"Olive oil","amount_g":30},{"name":"Fresh basil","amount_g":35},{"name":"Garlic","amount_g":12}]'::jsonb,
 '[{"text":"Toast bread until crisp outside but chewy within; rub lightly with garlic."},{"text":"Toss tomato and beans with basil, vinegar, pepper and oil."},{"text":"Heap onto toast only at serving time."}]'::jsonb,'Wholegrain toast with juicy tomato, basil and cannellini beans.'),
('recipe_award_sunomono','Sunomono with Edamame','snack','Japanese','Japan','vegan','japanese-sunomono-edamame.webp',190,12,7,94,array['soy','sesame'],
 '[{"name":"Cucumber","amount_g":700},{"name":"Shelled edamame","amount_g":400},{"name":"Wakame","amount_g":20},{"name":"Rice vinegar","amount_g":80},{"name":"Sesame seeds","amount_g":25},{"name":"Tamari","amount_g":20}]'::jsonb,
 '[{"text":"Salt ribboned cucumber lightly for ten minutes, then squeeze gently."},{"text":"Rehydrate wakame and cook edamame; cool both."},{"text":"Toss with rice vinegar, tamari, ginger and sesame just before serving."}]'::jsonb,'Cucumber, wakame and edamame in a bright sesame-rice-vinegar dressing.')
), rows as (
 select id,name,slot,cuisine,origin,diet,image,kcal,protein,fiber,score,allergens,ingredients,instructions,description,
   jsonb_build_object('energy_kcal',kcal,'protein_g',protein,'fiber_g',fiber,'_derivation',jsonb_build_object('method','ingredient-weight estimate','source','USDA FoodData Central reference foods','basis','prepared recipe / 4 servings','needs_curation',false)) nutrition,
   jsonb_build_object('vegan',diet='vegan','vegetarian',true,'egg_free',not ('egg'=any(allergens)),'dairy_free',not ('milk'=any(allergens)),'contains_nut',('peanut'=any(allergens) or 'cashew'=any(allergens) or 'walnut'=any(allergens)),'contains_soy','soy'=any(allergens),'contains_sesame','sesame'=any(allergens)) dietary
 from source
)
insert into public.catalog_recipes (id,name_common,category,category_sub,meal_slot,cuisine,origin,language,difficulty,prep_time,cook_time,servings,serving_size,description,description_simple,description_technical,ingredients,instructions,nutrition_per_serving,health_score,taste_profile,dietary_info,allergens,tags,image_url,image_primary_url,is_primary,scannable,updated_at)
select id,name,'meal',jsonb_build_array(initcap(slot),'Award-ranked'),slot,cuisine,origin,'en','medium','20 min','35 min',4,'1 plated serving',description,description,
 'A culturally grounded, plant-forward formulation with gram weights. Nutrition is a reference-food estimate, not a laboratory analysis.',ingredients,instructions,nutrition,score,
 '{"taste":{"sweet":3,"sour":3,"salty":3,"bitter":1,"umami":5,"spicy":3},"texture":{"creamy":3,"crispy":3,"chewy":3}}'::jsonb,dietary,allergens,
 array['award-ranked','world-class','plant-forward',diet,lower(replace(cuisine,' ','-'))],
 'https://healthscan.live/images/recipes/world/'||image,'https://healthscan.live/images/recipes/world/'||image,true,true,now()
from rows
on conflict (id) do update set name_common=excluded.name_common, category=excluded.category, category_sub=excluded.category_sub, meal_slot=excluded.meal_slot, cuisine=excluded.cuisine, origin=excluded.origin, description=excluded.description, description_simple=excluded.description_simple, description_technical=excluded.description_technical, ingredients=excluded.ingredients, instructions=excluded.instructions, nutrition_per_serving=excluded.nutrition_per_serving, health_score=excluded.health_score, taste_profile=excluded.taste_profile, dietary_info=excluded.dietary_info, allergens=excluded.allergens, tags=excluded.tags, image_url=excluded.image_url, image_primary_url=excluded.image_primary_url, updated_at=now();

notify pgrst, 'reload schema';
